"""Date-window membership for the date_window fixture."""

from __future__ import annotations

import datetime


def _parse_date(date_str: str) -> datetime.date:
    """Parse and validate a date string in strict ISO format YYYY-MM-DD."""
    if not isinstance(date_str, str):
        raise ValueError(f"Expected a string, got {type(date_str)}")
    # Check format strictly
    if len(date_str) != 10:
        raise ValueError(f"Invalid date format: {date_str!r}")
    parts = date_str.split("-")
    if len(parts) != 3:
        raise ValueError(f"Invalid date format: {date_str!r}")
    year_s, month_s, day_s = parts
    if len(year_s) != 4 or len(month_s) != 2 or len(day_s) != 2:
        raise ValueError(f"Invalid date format (missing zero padding): {date_str!r}")
    try:
        year = int(year_s)
        month = int(month_s)
        day = int(day_s)
    except ValueError:
        raise ValueError(f"Invalid date format (non-integer components): {date_str!r}")
    # Verify zero-padding by re-formatting
    if f"{year:04d}-{month:02d}-{day:02d}" != date_str:
        raise ValueError(f"Invalid date format (zero padding mismatch): {date_str!r}")
    try:
        return datetime.date(year, month, day)
    except ValueError:
        raise ValueError(f"Invalid calendar date: {date_str!r}")


def in_any_window(target_date: str, windows: list[tuple[str, str]]) -> bool:
    """Return whether target_date falls inside any date window."""
    # Parse and validate target date first
    target = _parse_date(target_date)

    # Parse and validate all windows before checking membership
    parsed_windows = []
    for start_str, end_str in windows:
        start = _parse_date(start_str)
        end = _parse_date(end_str)
        if start > end:
            raise ValueError(
                f"Window start {start_str!r} is after end {end_str!r}"
            )
        parsed_windows.append((start, end))

    # Now check membership
    for start, end in parsed_windows:
        if start <= target <= end:
            return True

    return False
